 add(['MX5-018'],'editorial_framing_separate_from_notice','《把农业互助合作当作一件大事去做》的1977版网页题注使用针对刘少奇的强烈政治评价。研究时应把该题注的后出解释，与1951年通知正文的内容及其原始行文目的分开，不把题注评价直接回填为1951年作者原话。',[web('MX5-018')],'1951年正文／1977版题注','对网页中题注与正文层次的观察',limit='这里指出归因层次，不凭其政治措辞就反向断言全部题注事实错误。')
 add(['MX5-044'],'specified_textual_changes_reported_by_letter','年谱1955年10月13日条转录征求第三次修正稿意见的信，列出合并章节、增加解释工农联盟的一节、替换适用地区表述、删例以及补入重质量、停顿间歇和及时批评等修改。此处已经有“改了什么”的具体来源陈述。',[p('A-08e901d73dcd78e98c4b',455)],'1955-10-13','年谱转录作者征求意见信',cause='信中列举具体修改并征求意见；不能把同年所有农业政策事件自动当作这些修改的唯一原因。')
 add(['MX5-044'],'reported_revision_count_not_six_extant_drafts','年谱接续1955年10月14日讲话，载作者说农业合作化报告经过六次修改。应保存这个“作者报告次数”，与10月13日信中的“第三次修正稿”标签分别记录，不能伪造六份已经获得的稿本。',[p('A-08e901d73dcd78e98c4b',455,456)],'1955-10-14','年谱转录作者讲话')
 add(['MX5-048'],'selection_of_annotations','《中国农村的社会主义高潮》的按语题注明确区分写过104篇与本卷选辑43篇，还提到1958年的部分重印说明。“未收入的61篇”首先是选编边界，不是61篇内容丢失或被同一次修改删除。',[web('MX5-048')],'1955年写作／1958年重印／1977年选编','网站转录的第五卷题注',limit='104和43是题注报告的篇数；本轮未据此认证原书所有按语已逐篇校齐。')
 add(['MX5-051'],'internal_circulation_for_future_revision','年谱1965年12月条记载《论十大关系》拟发县团以上学习，毛泽东18日批示不大满意，发下去征求意见以助将来修改。“内部征求意见”与“公开定本”必须分开。',[p('A-93d18940d055820ccb0b',552)],'1965-12-18','年谱转录批示')
 add(['MX5-051'],'public_release_deferred','年谱1975年7月13日条载审阅《论十大关系》整理稿和公开发表请示，批示暂不公开、可印发全党讨论、不登报，将来出选集再公开。批准内部流转不等于批准即时公开发表。',[p('A-bc29fda8b40043e7d0d2',603)],'1975-07-13','年谱转录批示',limit='该证据只确认1975年的整理与发布决定；1956年至此的完整稿本链未恢复。')
 add(['MX5-058'],'speech_edited_before_publication','《正处》网页题注记载根据讲话原始记录整理并作补充，1957年6月19日发表。它现在只是全书229篇之一，保留原专题，不替代全书研究。',[web('MX5-058')],'1957-02-27讲话／1957-06-19发表','网站转录的第五卷题注')
 add(['MX5-059'],'later_prepublication_review','年谱1964年3月14日条记载，将1957年全国宣传工作会议讲话整理稿交康生、陈伯达看并提修改意见，拟收入新简选本；页下注说明1964年6月收入《毛泽东著作选读》甲种本。1957年的题下日期不等于1964年编选审核日期。',[p('A-93d18940d055820ccb0b',327,328)],'1957年讲话／1964-03-14审核／1964-06编入','年谱转录批示和编者出版说明')
 add(['MX5-060'],'two_speeches_compiled','《坚持艰苦奋斗，密切联系群众》题注区分1957年3月18日济南讲话的一部分与3月19日南京讲话的一部分。两地讲话在选集里并为一篇，不能互当改稿。',[web('MX5-060')],'1957-03-18／1957-03-19','网站转录的第五卷题注')
 add(['MX5-066'],'dated_sequence_of_revision_reports','年谱1957年7月19—30日条逐日记载《一九五七年夏季的形势》草稿及第一至第十次修改稿：19日草稿及第一次，20日第二和第三次，25日第四次，26—27日第五至第八次，29日第九次，30日第十次。是有来源的“版本事件骨架”，不是已拥有全部稿本的逐字diff链。',[p('A-264a603d150bc5388914',196,197)],'1957-07-19／1957-07-30','年谱逐日修订记载（关键日期已对照页图）',limit='第197页既有文字层明显乱码，事件据已查看的页图核对；原始提取文本不作静默修正。尚未逐份取得和比对十次稿本。')
 add(['MX5-066'],'distribution_scope_and_approval_state_change','同篇年谱记载，第三次稿拟发至地委一级，第四次稿拟发至县委及相当一级；第十次稿虽称最后定稿，仍要求交政治局批准，如有修改须告知。发放层级和审核状态都是演变信息，不能只比文字。',[p('A-264a603d150bc5388914',196,197)],'1957-07-20／1957-07-25／1957-07-30','年谱转录稿上说明、批示（已核关键页图）')
 add(['MX5-069','MX5-070'],'same_meeting_different_excerpts','《党内团结的辩证方法》和《一切反动派都是纸老虎》网页题注都标为莫斯科共产党和工人党代表会议发言的节录。应优先核对母发言与节录范围，不能仅因日期相同就认定两篇相互修订。',[web('MX5-069'),web('MX5-070')],'1957-11-18','网站转录的第五卷题注',limit='共同会议和节录属性有题注支持；是否同一完整母发言及精确段落范围仍待母稿校核。')
